Which token does each tool use, and what happens if write tools are disabled?
```python
import os
READ, WRITE = 'read-tok', os.environ.get('GITHUB_WRITE_TOKEN')
reads = {'list_issues', 'get_issue'}
def token_for(tool):
    if tool in reads:
        return READ
    if WRITE is None:
        raise PermissionError(f'{tool} needs the write token, which is not configured')
    return WRITE
print(token_for('list_issues'))
try:
    token_for('create_issue')
except PermissionError as e:
    print(e)
```

Do reordered arguments hit the same cache entry, and does the TTL expire it?
```python
import hashlib, json, time
class Cache:
    def __init__(self, ttl):
        self.ttl, self.s = ttl, {}
    def key(self, tool, args):
        return hashlib.sha256(f'{tool}:{json.dumps(args, sort_keys=True)}'.encode()).hexdigest()
    def set(self, tool, args, v):
        self.s[self.key(tool, args)] = (time.monotonic(), v)
    def get(self, tool, args):
        e = self.s.get(self.key(tool, args))
        if e is None or time.monotonic() - e[0] > self.ttl:
            return None
        return e[1]
c = Cache(ttl=0.05)
c.set('get_issue', {'repo': 'x', 'n': 1}, 'cached')
print(c.get('get_issue', {'n': 1, 'repo': 'x'}))
time.sleep(0.1)
print(c.get('get_issue', {'n': 1, 'repo': 'x'}))
```

